from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(9,'comparer-decimaux','Comparer et arrondir les décimaux','2 · Fractions et nombres décimaux',
'Ordre · Encadrements · Partie entière · Arrondis',
['Comparer, encadrer et intercaler des nombres décimaux.','Placer des décimaux sur une demi-droite graduée.','Donner la partie entière et l’arrondi à l’entier.'],
['Écriture à virgule, dixièmes et centièmes.'],[
page(1,'Comparer et ranger',
bloc('propriete',r'Pour comparer deux décimaux : comparer d’abord les parties entières ; si elles sont égales, comparer les chiffres des dixièmes, puis ceux des centièmes. Ainsi $6{,}8>6{,}08$, car 8 dixièmes dépassent 0 dixième.'),
bloc('exemple',r'Comparer $3{,}5$ et $3{,}45$ : écrire $3{,}5=3{,}50$. Comme $50$ centièmes dépassent $45$ centièmes, $3{,}5>3{,}45$. Un nombre n’est pas plus grand parce qu’il a plus de chiffres.'),
r'@FIG:cours-droite-decimaux@',
bloc('savoirfaire',r'Entre deux décimaux, on peut toujours en intercaler un autre : entre $2{,}4$ et $2{,}5$, penser en centièmes : $2{,}40<2{,}45<2{,}50$. Ajouter un rang suffit pour affiner.','Intercaler un nombre')),
page(2,'Partie entière et arrondi',
bloc('definition',r'La partie entière de $17{,}83$ est 17 : c’est le nombre entier juste avant. On a l’encadrement $17<17{,}83<18$ entre deux entiers consécutifs.'),
bloc('propriete',r'L’arrondi à l’entier est l’entier le plus proche. Si le chiffre des dixièmes est 0, 1, 2, 3 ou 4, on garde la partie entière ; sinon on prend l’entier suivant. L’arrondi de $7{,}3$ est 7 ; celui de $7{,}83$ est 8. Pour $12{,}5$, à égale distance, on choisit 13.'),
bloc('exemple',r'Sur la demi-droite, $7{,}83$ est plus près de 8 que de 7 : l’arrondi se voit sur les positions. Un prix de $7{,}83$ euros est proche de 8 euros : l’arrondi aide à estimer.'),
bloc('attention',r'Arrondir n’est pas tronquer : l’arrondi de $9{,}8$ est 10, pas 9. Et deux nombres arrondis au même entier restent différents : l’arrondi sert à estimer, pas à remplacer la valeur exacte.'))
],[
E('Le piège classique',r'Comparer $3{,}5$ et $3{,}45$.',r'$3{,}5=3{,}50$ : cinquante centièmes contre quarante-cinq. Donc $\res{3{,}5>3{,}45}$.','Écrire les deux nombres avec deux chiffres après la virgule.','assert Rational("3.5")>Rational("3.45")'),
E('Compléter par un symbole',r'Compléter par $<$ ou $>$ : $6{,}08\ \ldots\ 6{,}8$, puis $12{,}34\ \ldots\ 9{,}99$.',r'Parties entières égales puis $0<8$ aux dixièmes : $\res{6{,}08<6{,}8}$. Les parties entières décident ensuite : $\res{12{,}34>9{,}99}$.','Comparer rang par rang depuis la gauche.','assert Rational("6.08")<Rational("6.8") and Rational("12.34")>Rational("9.99")'),
E('Ranger cinq nombres',r'Ranger dans l’ordre croissant : $7{,}3$ ; $7{,}09$ ; $7{,}31$ ; $7{,}1$ ; $6{,}99$.',r'$6{,}99$ a la plus petite partie entière. Ensuite, comparer les dixièmes puis les centièmes : $\res{6{,}99<7{,}09<7{,}1<7{,}3<7{,}31}$.','Aligner mentalement les rangs décimaux.','assert Rational("6.99")<Rational("7.09")<Rational("7.1")<Rational("7.3")<Rational("7.31")'),
E('Encadrer par des entiers',r'Encadrer chaque nombre entre deux entiers consécutifs : $4{,}62$, puis $0{,}85$.',r'$\res{4<4{,}62<5}$ et $\res{0<0{,}85<1}$. La partie entière donne la borne de gauche.','Lire la partie entière.','assert 4<Rational("4.62")<5 and 0<Rational(".85")<1'),
E('Partie entière',r'Donner la partie entière de $17{,}83$, de $9{,}04$ et de $0{,}76$.',r'Les parties entières sont $\res{17}$, $\res9$ et $\res0$.','Prendre l’entier juste avant le nombre.','assert 17<=Rational("17.83")<18 and 9<=Rational("9.04")<10 and 0<=Rational(".76")<1'),
E('Lire entre les graduations',r'La demi-droite est graduée de $0{,}1$ en $0{,}1$. Lire les abscisses de A et B, puis placer $C(5{,}45)$.',r'$\res{A(5{,}3)}$ et $\res{B(5{,}8)}$. Le point C se place au milieu du pas entre $5{,}4$ et $5{,}5$ ; il figure en vert sur le corrigé.','Identifier la valeur d’un pas avant de lire.','assert Rational("5.3")<Rational("5.45")<Rational("5.5")',figure='dec9-6'),
E('Intercaler',r'Donner un nombre compris entre $2{,}4$ et $2{,}5$, puis un nombre compris entre $8{,}31$ et $8{,}32$.',r'En centièmes : $\res{2{,}45}$ convient, car $2{,}40<2{,}45<2{,}50$. En ajoutant un rang : $\res{8{,}315}$ convient ; tout nombre strictement entre les bornes est accepté.','Ajouter un rang décimal pour affiner.','assert Rational("2.4")<Rational("2.45")<Rational("2.5") and Rational("8.31")<Rational("8.315")<Rational("8.32")'),
E('Arrondir à l’entier',r'Donner l’arrondi à l’entier de $7{,}3$, de $7{,}83$ et de $12{,}5$.',r'$7{,}3$ est plus proche de 7 : arrondi $\res7$. $7{,}83$ est plus proche de 8 : arrondi $\res8$. $12{,}5$ est à égale distance : on choisit $\res{13}$.','Regarder le chiffre des dixièmes.','assert abs(Rational("7.3")-7)<abs(Rational("7.3")-8) and abs(Rational("7.83")-8)<abs(Rational("7.83")-7) and Rational("12.5")-12==13-Rational("12.5")'),
E('Compter de 0,1 en 0,1',r'Compter de $0{,}1$ en $0{,}1$ à partir de $3{,}7$, jusqu’à dépasser 4. Écrire les nombres obtenus.',r'$3{,}7$ ; $3{,}8$ ; $3{,}9$ ; $\res{4}$ ; $4{,}1$. Dix dixièmes font une unité : après $3{,}9$ vient 4, et non « $3{,}10$ ».','Échanger dix dixièmes contre une unité.','assert Rational("3.9")+Rational(".1")==4 and 4+Rational(".1")==Rational("4.1")'),
E('Le même nombre ?',r'Dire si les écritures désignent le même nombre : $5{,}60$ et $5{,}6$ ; $5{,}06$ et $5{,}6$ ; $07{,}2$ et $7{,}2$.',r'$5{,}60=\res{5{,}6}$ : le zéro final des centièmes ne change rien. $5{,}06\ne5{,}6$ : $\res{\text{différents}}$. $07{,}2=\res{7{,}2}$ : le zéro de gauche est inutile.','Situer chaque zéro par rapport aux rangs.','assert Rational("5.60")==Rational("5.6") and Rational("5.06")!=Rational("5.6")'),
E('Le podium du saut',r'Aux essais, Lina saute $3{,}45$ m, Maya $3{,}5$ m et Inès $3{,}09$ m. Donner le classement de la meilleure à la moins bonne performance.',r'$3{,}5=3{,}50$ dépasse $3{,}45$, qui dépasse $3{,}09$ : $\res{\text{Maya, puis Lina, puis Inès}}$. L’ordre décroissant des longueurs est $3{,}5>3{,}45>3{,}09$.','Égaliser le nombre de chiffres avant de comparer.','assert Rational("3.5")>Rational("3.45")>Rational("3.09")'),
E('La toise de la classe',r'Quatre élèves mesurent $1{,}38$ m, $1{,}4$ m, $1{,}29$ m et $1{,}33$ m. Les ranger du plus petit au plus grand.',r'En centièmes : $129$, $133$, $138$, $140$. L’ordre croissant est $\res{1{,}29<1{,}33<1{,}38<1{,}4}$.','Penser chaque taille en centimètres.','assert Rational("1.29")<Rational("1.33")<Rational("1.38")<Rational("1.4")'),
E('Toujours un intermédiaire ?',r'Donner deux nombres différents compris entre $6{,}2$ et $6{,}3$. Peut-on toujours trouver un nombre entre deux décimaux différents ? Expliquer.',r'Par exemple $\res{6{,}24}$ et $\res{6{,}27}$. $\res{\text{Oui}}$ : en écrivant les deux nombres avec un rang de plus, des écritures intermédiaires apparaissent toujours ; la demi-droite n’a pas de « trous ».','Passer aux centièmes, voire aux rangs suivants.','assert Rational("6.2")<Rational("6.24")<Rational("6.27")<Rational("6.3")'),
E('L’étiquette effacée',r'Dans un magasin, un paquet coûte $4{,}05$ euros et un autre $4{,}5$ euros. Tom pense que $4{,}05$ est le plus cher « car 05 vient après 5 ». Corriger son raisonnement.',r'$4{,}5=4{,}50$ : cinquante centimes contre cinq centimes. Le paquet à $\res{4{,}05}$ euros est le moins cher, avec $4{,}50-4{,}05=0{,}45$ euro d’écart. On compare des rangs, pas des écritures.','Donner la même longueur décimale aux deux prix.','assert Rational("4.05")<Rational("4.5") and Rational("4.50")-Rational("4.05")==Rational(".45")'),
E('L’erreur de rangement',r'Aya écrit : « $12{,}34>12{,}5$ car $34>5$. » Expliquer son erreur, donner la bonne comparaison, puis l’arrondi à l’entier des deux nombres.',r'Aya compare « 34 » et « 5 » comme des entiers ; or il faut comparer rang par rang : 3 dixièmes contre 5 dixièmes, donc $\res{12{,}34<12{,}5}$. Les arrondis sont $\res{12}$ et $\res{13}$ : $12{,}5$ est à égale distance et s’arrondit au-dessus.','Comparer les dixièmes avec les dixièmes.','assert Rational("12.34")<Rational("12.5") and abs(Rational("12.34")-12)<abs(Rational("12.34")-13)')
],reperes=['Comparer rang par rang','Encadrer et intercaler','Demi-droite et graduations fines','Partie entière, arrondis et problèmes'],deco='calcul')

chapitre(10,'calculer-decimaux','Calculer avec les décimaux','2 · Fractions et nombres décimaux',
'Sommes · Différences · Produits par un entier',
['Poser des additions et soustractions de décimaux.','Multiplier un décimal par 10 et par un entier inférieur à 10.','Résoudre des problèmes de mesures et de monnaie.'],
['Rangs décimaux et opérations posées sur les entiers.'],[
page(1,'Additionner et soustraire',
bloc('savoirfaire',r'Poser une addition ou une soustraction de décimaux, c’est aligner les virgules : unités sous unités, dixièmes sous dixièmes. Compléter les rangs vides par des zéros : pour $10-3{,}48$, écrire $10{,}00$.','Aligner les virgules'),
bloc('exemple',r'$4{,}7+2{,}85$ : on pose $4{,}70+2{,}85$. $0+5$ centièmes, $7+8$ dixièmes font 15 dixièmes : on écrit 5 et on retient une unité. Résultat : $7{,}55$. Estimation : proche de $5+3=8$.'),
bloc('propriete',r'Les techniques des entiers s’appliquent rang par rang : dix centièmes s’échangent contre un dixième, dix dixièmes contre une unité. La virgule du résultat s’aligne sous les autres.'),
bloc('savoirfaire',r'De tête : ajouter un entier ne touche que la partie entière ($5{,}34+2=7{,}34$). Chercher les compléments : $0{,}35+0{,}65=1$ et $7{,}2+2{,}8=10$. Pour rendre la monnaie sur 10 euros après $7{,}45$ : $7{,}45\to7{,}50\to8\to10$, soit $2{,}55$.','Calculer de tête')),
page(2,'Multiplier un décimal',
bloc('propriete',r'Multiplier par 10 fait monter chaque chiffre d’un rang : $3{,}7\times10=37$ et $0{,}85\times10=8{,}5$. Diviser par 10 fait l’inverse : $45{,}2:10=4{,}52$. La virgule semble glisser : ce sont les chiffres qui changent de rang.'),
bloc('exemple',r'$2{,}4\times3$ : 24 dixièmes multipliés par 3 font 72 dixièmes, soit $7{,}2$. Pour $3{,}45\times6$ : $345$ centièmes $\times\,6=2\,070$ centièmes, soit $20{,}70=20{,}7$. Estimation : $3{,}5\times6=21$.'),
bloc('savoirfaire',r'Poser $3{,}45\times6$ comme $345\times6$, puis replacer la virgule : le résultat garde deux chiffres après la virgule, comme $3{,}45$. Toujours contrôler avec un ordre de grandeur.','Poser un produit par un entier'),
bloc('attention',r'Multiplier par 10 n’ajoute pas un zéro à un décimal : $3{,}7\times10$ ne fait pas « $3{,}70$ » mais 37. Penser aux rangs : chaque chiffre devient dix fois plus grand.'))
],[
E('Une somme posée',r'Poser et calculer $4{,}7+2{,}85$.',r'En alignant les virgules : $4{,}70+2{,}85=\res{7{,}55}$. L’estimation $5+3=8$ confirme l’ordre de grandeur.','Compléter $4{,}7$ en $4{,}70$.','assert Rational("4.7")+Rational("2.85")==Rational("7.55")'),
E('Une différence posée',r'Poser et calculer $10-3{,}48$.',r'On écrit $10{,}00-3{,}48=\res{6{,}52}$. Contrôle : $6{,}52+3{,}48=10$.','Écrire 10 avec deux chiffres après la virgule.','assert 10-Rational("3.48")==Rational("6.52") and Rational("6.52")+Rational("3.48")==10'),
E('De tête, sans retenue',r'Calculer mentalement $5{,}34+2$, puis $5{,}34+0{,}2$, puis $7{,}89-4$.',r'L’entier ne touche que la partie entière : $\res{7{,}34}$. Les dixièmes s’ajoutent aux dixièmes : $\res{5{,}54}$. Et $7{,}89-4=\res{3{,}89}$.','Ajouter chaque nombre au bon rang.','assert Rational("5.34")+2==Rational("7.34") and Rational("5.34")+Rational(".2")==Rational("5.54") and Rational("7.89")-4==Rational("3.89")'),
E('Par 10, dans les deux sens',r'Calculer $3{,}7\times10$ ; $0{,}85\times10$ ; $45{,}2:10$.',r'Chaque chiffre monte d’un rang : $\res{37}$ et $\res{8{,}5}$. Pour la division, chaque chiffre descend : $\res{4{,}52}$.','Déplacer les chiffres d’un rang, pas « ajouter un zéro ».','assert Rational("3.7")*10==37 and Rational(".85")*10==Rational("8.5") and Rational("45.2")/10==Rational("4.52")'),
E('Un produit en dixièmes',r'Calculer $2{,}4\times3$ en raisonnant en dixièmes.',r'24 dixièmes $\times\,3=72$ dixièmes, soit $\res{7{,}2}$. Contrôle : $2{,}4\times3$ est proche de $2\times3=6$ et dépasse 7 de peu.','Convertir en dixièmes, multiplier, reconvertir.','assert Rational("2.4")*3==Rational("7.2")'),
E('Compléments utiles',r'Compléter : $0{,}35+\square=1$, puis $7{,}2+\square=10$.',r'$0{,}35+0{,}65=1$ : le complément est $\res{0{,}65}$. $7{,}2+2{,}8=10$ : le complément est $\res{2{,}8}$.','Compléter d’abord les centièmes, puis les unités.','assert Rational(".35")+Rational(".65")==1 and Rational("7.2")+Rational("2.8")==10'),
E('Un produit posé',r'Poser et calculer $3{,}45\times6$.',r'$345\times6=2\,070$, donc $3{,}45\times6=\res{20{,}70}$, c’est-à-dire $20{,}7$. L’estimation $3{,}5\times6=21$ valide le résultat.','Compter les chiffres après la virgule du facteur décimal.','assert Rational("3.45")*6==Rational("20.70")'),
E('Regrouper pour simplifier',r'Calculer $2{,}6+4{,}85+0{,}4$ en regroupant deux termes bien choisis.',r'$2{,}6+0{,}4=3$, puis $3+4{,}85=\res{7{,}85}$. L’ordre des termes d’une somme peut changer.','Chercher un total rond.','assert Rational("2.6")+Rational(".4")==3 and Rational("2.6")+Rational("4.85")+Rational(".4")==Rational("7.85")'),
E('Contrôler une soustraction',r'Noé calcule $8-2{,}35=6{,}35$. Vérifier avec une addition et corriger si besoin.',r'$6{,}35+2{,}35=8{,}70\ne8$ : le résultat est faux. Le bon calcul : $8{,}00-2{,}35=\res{5{,}65}$ ; contrôle : $5{,}65+2{,}35=8$.','Toujours vérifier une différence par la somme.','assert Rational("6.35")+Rational("2.35")==Rational("8.70") and 8-Rational("2.35")==Rational("5.65")'),
E('Rendre la monnaie',r'Un achat coûte $7{,}45$ euros, payé avec un billet de 10 euros. Calculer la monnaie rendue en passant par des étapes simples.',r'$7{,}45\to7{,}50$ : 5 centimes ; $7{,}50\to8$ : 50 centimes ; $8\to10$ : 2 euros. La monnaie est $0{,}05+0{,}50+2=\res{2{,}55}$ euros.','Avancer de palier en palier jusqu’au billet.','assert 10-Rational("7.45")==Rational("2.55") and Rational(".05")+Rational(".50")+2==Rational("2.55")'),
E('Le panier de courses',r'Une baguette coûte $1{,}20$ euro, une plaquette de beurre $2{,}85$ euros et une brique de lait $1{,}15$ euro.'+Q(r'Calculer la dépense totale.',r'Quelle monnaie rend-on sur un billet de 10 euros ?'),r'La dépense vaut $1{,}20+2{,}85+1{,}15=\res{5{,}20}$ euros ; regrouper $1{,}20+1{,}15=2{,}35$ aide peu, mieux vaut $2{,}85+1{,}15=4$. La monnaie : $10-5{,}20=\res{4{,}80}$ euros.','Chercher des paires qui font un compte rond.','assert Rational("1.20")+Rational("2.85")+Rational("1.15")==Rational("5.20") and 10-Rational("5.20")==Rational("4.80")'),
E('Les sorties du coureur',r'Un coureur parcourt $4{,}5$ km lundi, puis $1{,}8$ km de moins mardi. Quelle distance parcourt-il mardi ? Et sur les deux jours ?',r'Mardi : $4{,}5-1{,}8=\res{2{,}7}$ km. Total : $4{,}5+2{,}7=\res{7{,}2}$ km. « De moins » conduit ici à une soustraction puis à une addition.','Calculer la donnée manquante avant le total.','assert Rational("4.5")-Rational("1.8")==Rational("2.7") and Rational("4.5")+Rational("2.7")==Rational("7.2")'),
E('Trois carnets identiques',r'Un carnet coûte $2{,}45$ euros. Calculer le prix de trois carnets, puis la monnaie rendue sur 10 euros.',r'$2{,}45\times3=\res{7{,}35}$ euros. Monnaie : $10-7{,}35=\res{2{,}65}$ euros. Estimation : $2{,}5\times3=7{,}5$, proche du prix exact.','Multiplier avant de soustraire.','assert Rational("2.45")*3==Rational("7.35") and 10-Rational("7.35")==Rational("2.65")'),
E('Le ruban coupé',r'Dans un ruban de $2{,}75$ m, on coupe deux morceaux de $0{,}9$ m chacun. Quelle longueur de ruban reste-t-il ?',r'Les morceaux prennent $0{,}9\times2=1{,}8$ m. Il reste $2{,}75-1{,}8=\res{0{,}95}$ m. Contrôle : $1{,}8+0{,}95=2{,}75$ m.','Calculer d’abord la longueur totale coupée.','assert Rational(".9")*2==Rational("1.8") and Rational("2.75")-Rational("1.8")==Rational(".95")'),
E('L’alignement fautif',r'Tom pose $5{,}6+2{,}14$ en alignant les nombres à droite, comme des entiers, et trouve $2{,}70$. Expliquer son erreur et donner le bon résultat.',r'Tom a ajouté des centièmes à des dixièmes : les rangs étaient décalés. En alignant les virgules : $5{,}60+2{,}14=\res{7{,}74}$. L’estimation $6+2=8$ aurait signalé l’erreur.','Aligner les virgules, pas les derniers chiffres.','assert Rational("5.6")+Rational("2.14")==Rational("7.74")')
],reperes=['Poser avec les virgules alignées','Calcul mental et compléments','Multiplier par 10 et par un entier','Monnaie, mesures et contrôles'],deco='calcul')
